        b.add(2);
        b.add(3);
        b.remove(Integer.valueOf(1));      // 値1
        System.out.println("remove(Integer.valueOf(1)): " + b);

        // 文字列なら迷わない
        List<String> c = new ArrayList<>();
        c.add("a");
        c.add("b");
        c.remove("a");
        System.out.println("remove(\"a\")            : " + c);
    }
}

import java.util.ArrayList;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        List<Integer> bad = new ArrayList<>(List.of(1, 1, 2));
        for (int i = 0; i < bad.size(); i++) {
            if (bad.get(i) == 1) {
                bad.remove(i);            // ずれる
            }
        }
        System.out.println("前から回した : " + bad);

        List<Integer> good = new ArrayList<>(List.of(1, 1, 2));
        for (int i = good.size() - 1; i >= 0; i--) {
            if (good.get(i) == 1) {
                good.remove(i);           // 後ろからならずれない
            }
        }
        System.out.println("後ろから回した: " + good);

        List<Integer> loop = new ArrayList<>(List.of(1, 1, 2));
        try {
            for (Integer n : loop) {
                loop.remove(n);
            }
        } catch (Exception e) {
            System.out.println("拡張for の中で削除: " + e.getClass().getSimpleName());
        }
    }
}

