import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.Set;
import java.util.TreeSet;

public class Main {
    public static void main(String[] args) {
        String[] words = {"c", "a", "b", "a", "c"};

        Set<String> hash = new HashSet<>();
        Set<String> linked = new LinkedHashSet<>();
        Set<String> tree = new TreeSet<>();

        for (String w : words) {
            hash.add(w);
            linked.add(w);
            tree.add(w);
        }

        System.out.println("個数        : " + linked.size());
        System.out.println("LinkedHash  : " + linked);      // 追加した順
        System.out.println("TreeSet     : " + tree);        // 辞書順
        System.out.println("HashSet     : " + hash);        // 順番は保証なし

        System.out.println("add の戻り値: " + linked.add("a") + " / " + linked.add("z"));
    }
}

import java.util.ArrayList;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        List<String> fixed = List.of("a", "b");
        System.out.println("読むのは自由: " + fixed.get(0) + " / " + fixed.size());

        try {
            fixed.add("c");
        } catch (UnsupportedOperationException e) {
            System.out.println("変更できません");
        }

        // 詰め替えれば変更できる
        List<String> mutable = new ArrayList<>(List.of("a", "b"));
        mutable.add("c");
        System.out.println("詰め替えた後: " + mutable);
    }
}

